cboe_cfefutures_binaryorderentry_boe_v1_3_12.fee_code.size = 2

-- Display: Fee Code
cboe_cfefutures_binaryorderentry_boe_v1_3_12.fee_code.display = function(value)
  -- Check if field has value
  if value == nil or value == '' then
    return "Fee Code: No Value"
  end

  return "Fee Code: "..value
end

-- Dissect: Fee Code
cboe_cfefutures_binaryorderentry_boe_v1_3_12.fee_code.dissect = function(buffer, offset, packet, parent)
  local length = cboe_cfefutures_binaryorderentry_boe_v1_3_12.fee_code.size
  local range = buffer(offset, length)

  -- parse last octet
  local last = buffer(offset + length - 1, 1):uint()

  -- read full string or up to first zero
  local value = ''
  if last == 0 then
    value = range:stringz()
  else
    value = range:string()
  end

  local display = cboe_cfefutures_binaryorderentry_boe_v1_3_12.fee_code.display(value, buffer, offset, packet, parent)

  parent:add(omi_cboe_cfefutures_binaryorderentry_boe_v1_3_12.fields.fee_code, range, value, display)

  return offset + length, value
end

