  local flags = {}

  -- Is Order Execution Return Bitfield 1 Side flag set?
  if bit.band(value, 0x01) ~= 0 then
    flags[#flags + 1] = "Order Execution Return Bitfield 1 Side"
  end
  -- Is Order Execution Return Bitfield 1 Peg Difference flag set?
  if bit.band(value, 0x02) ~= 0 then
    flags[#flags + 1] = "Order Execution Return Bitfield 1 Peg Difference"
  end
  -- Is Order Execution Return Bitfield 1 Price flag set?
  if bit.band(value, 0x04) ~= 0 then
    flags[#flags + 1] = "Order Execution Return Bitfield 1 Price"
  end
  -- Is Order Execution Return Bitfield 1 Exec Inst flag set?
  if bit.band(value, 0x08) ~= 0 then
    flags[#flags + 1] = "Order Execution Return Bitfield 1 Exec Inst"
  end
  -- Is Order Execution Return Bitfield 1 Order Type flag set?
  if bit.band(value, 0x10) ~= 0 then
    flags[#flags + 1] = "Order Execution Return Bitfield 1 Order Type"
  end
  -- Is Order Execution Return Bitfield 1 Time In Force flag set?
  if bit.band(value, 0x20) ~= 0 then
    flags[#flags + 1] = "Order Execution Return Bitfield 1 Time In Force"
  end
  -- Is Order Execution Return Bitfield 1 Min Qty flag set?
  if bit.band(value, 0x40) ~= 0 then
    flags[#flags + 1] = "Order Execution Return Bitfield 1 Min Qty"
  end
  -- Is Order Execution Return Bitfield 1 Max Remove Pct flag set?
  if bit.band(value, 0x80) ~= 0 then
    flags[#flags + 1] = "Order Execution Return Bitfield 1 Max Remove Pct"
  end

  return table.concat(flags, "|")
end

