  local flags = {}

  -- Is Order Acknowledgment Return Bitfield 18 Reserved 1 flag set?
  if bit.band(value, 0x01) ~= 0 then
    flags[#flags + 1] = "Order Acknowledgment Return Bitfield 18 Reserved 1"
  end
  -- Is Order Acknowledgment Return Bitfield 18 Cross Initiator flag set?
  if bit.band(value, 0x02) ~= 0 then
    flags[#flags + 1] = "Order Acknowledgment Return Bitfield 18 Cross Initiator"
  end
  -- Is Order Acknowledgment Return Bitfield 18 Subreason flag set?
  if bit.band(value, 0x04) ~= 0 then
    flags[#flags + 1] = "Order Acknowledgment Return Bitfield 18 Subreason"
  end
  -- Is Order Acknowledgment Return Bitfield 18 Reserved 8 flag set?
  if bit.band(value, 0x08) ~= 0 then
    flags[#flags + 1] = "Order Acknowledgment Return Bitfield 18 Reserved 8"
  end
  -- Is Order Acknowledgment Return Bitfield 18 Reserved 16 flag set?
  if bit.band(value, 0x10) ~= 0 then
    flags[#flags + 1] = "Order Acknowledgment Return Bitfield 18 Reserved 16"
  end
  -- Is Order Acknowledgment Return Bitfield 18 Reserved 32 flag set?
  if bit.band(value, 0x20) ~= 0 then
    flags[#flags + 1] = "Order Acknowledgment Return Bitfield 18 Reserved 32"
  end
  -- Is Order Acknowledgment Return Bitfield 18 Reserved 64 flag set?
  if bit.band(value, 0x40) ~= 0 then
    flags[#flags + 1] = "Order Acknowledgment Return Bitfield 18 Reserved 64"
  end
  -- Is Order Acknowledgment Return Bitfield 18 Reserved 128 flag set?
  if bit.band(value, 0x80) ~= 0 then
    flags[#flags + 1] = "Order Acknowledgment Return Bitfield 18 Reserved 128"
  end

  return table.concat(flags, "|")
