cboe_cfefutures_binaryorderentry_boe_v1_3_12.quote_update_message.fields = function(buffer, offset, packet, parent, size_of_quote_update_message)
  local index = offset

  -- Quote Update Id: Text
  index, quote_update_id = cboe_cfefutures_binaryorderentry_boe_v1_3_12.quote_update_id.dissect(buffer, index, packet, parent)

  -- Clearing Firm: Alpha
  index, clearing_firm = cboe_cfefutures_binaryorderentry_boe_v1_3_12.clearing_firm.dissect(buffer, index, packet, parent)

  -- Clearing Account: Text
  index, clearing_account = cboe_cfefutures_binaryorderentry_boe_v1_3_12.clearing_account.dissect(buffer, index, packet, parent)

  -- Cmta Number: Binary
  index, cmta_number = cboe_cfefutures_binaryorderentry_boe_v1_3_12.cmta_number.dissect(buffer, index, packet, parent)

  -- Account: Text
  index, account = cboe_cfefutures_binaryorderentry_boe_v1_3_12.account.dissect(buffer, index, packet, parent)

  -- Custom Group Id: Binary
  index, custom_group_id = cboe_cfefutures_binaryorderentry_boe_v1_3_12.custom_group_id.dissect(buffer, index, packet, parent)

  -- Capacity: Alpha
  index, capacity = cboe_cfefutures_binaryorderentry_boe_v1_3_12.capacity.dissect(buffer, index, packet, parent)

  -- Cti Code: Alphanumeric
  index, cti_code = cboe_cfefutures_binaryorderentry_boe_v1_3_12.cti_code.dissect(buffer, index, packet, parent)

  -- Manual Order Indicator: Alpha
  index, manual_order_indicator = cboe_cfefutures_binaryorderentry_boe_v1_3_12.manual_order_indicator.dissect(buffer, index, packet, parent)

  -- Oeoid: Text
  index, oeoid = cboe_cfefutures_binaryorderentry_boe_v1_3_12.oeoid.dissect(buffer, index, packet, parent)

  -- Size Modifier: Text
  index, size_modifier = cboe_cfefutures_binaryorderentry_boe_v1_3_12.size_modifier.dissect(buffer, index, packet, parent)

  -- Reserved 6: Reserved
  index, reserved_6 = cboe_cfefutures_binaryorderentry_boe_v1_3_12.reserved_6.dissect(buffer, index, packet, parent)

  -- Quote Cnt: Binary
  index, quote_cnt = cboe_cfefutures_binaryorderentry_boe_v1_3_12.quote_cnt.dissect(buffer, index, packet, parent)

  -- Repeating: Quote
  for quote_index = 1, quote_cnt do
    index, quote = cboe_cfefutures_binaryorderentry_boe_v1_3_12.quote.dissect(buffer, index, packet, parent, quote_index)
  end

  return index
end

