-- Read runtime size of: New Order Message
cboe_cfefutures_binaryorderentry_boe_v1_3_12.new_order_message.size = function(buffer, offset)
  local index = offset

  -- Dependency element: Message Length
  local message_length = buffer(offset - 8, 2):le_uint()

  return message_length - 8
end

-- Display: New Order Message
cboe_cfefutures_binaryorderentry_boe_v1_3_12.new_order_message.display = function(packet, parent, length)
  return ""
end

-- Dissect Fields: New Order Message
cboe_cfefutures_binaryorderentry_boe_v1_3_12.new_order_message.fields = function(buffer, offset, packet, parent, size_of_new_order_message)
  local index = offset

  -- Cl Ord Id: Text
  index, cl_ord_id = cboe_cfefutures_binaryorderentry_boe_v1_3_12.cl_ord_id.dissect(buffer, index, packet, parent)

  -- Side: Alphanumeric
  index, side = cboe_cfefutures_binaryorderentry_boe_v1_3_12.side.dissect(buffer, index, packet, parent)

  -- Order Qty: Binary
  index, order_qty = cboe_cfefutures_binaryorderentry_boe_v1_3_12.order_qty.dissect(buffer, index, packet, parent)

  -- Number Of New Order Bitfields: Binary
  index, number_of_new_order_bitfields = cboe_cfefutures_binaryorderentry_boe_v1_3_12.number_of_new_order_bitfields.dissect(buffer, index, packet, parent)

  -- Runtime optional field: New Order Bitfield 1
  local new_order_bitfield_1 = nil

  local new_order_bitfield_1_exists = number_of_new_order_bitfields >= 1

  if new_order_bitfield_1_exists then

    -- New Order Bitfield 1: Struct of 8 fields
    index, new_order_bitfield_1 = cboe_cfefutures_binaryorderentry_boe_v1_3_12.new_order_bitfield_1.dissect(buffer, index, packet, parent)
  end

  -- Runtime optional field: New Order Bitfield 2
  local new_order_bitfield_2 = nil

  local new_order_bitfield_2_exists = number_of_new_order_bitfields >= 2

  if new_order_bitfield_2_exists then

    -- New Order Bitfield 2: Struct of 8 fields
    index, new_order_bitfield_2 = cboe_cfefutures_binaryorderentry_boe_v1_3_12.new_order_bitfield_2.dissect(buffer, index, packet, parent)
  end

